-- Renames the floor table and its objects from office_floor to company_floor, so
-- the schema uses the product's name. Renames only: no index is built here, and
-- the rows, constraints and foreign-key-free relations are unchanged. The check
-- constraint name is generated by Postgres, so it is found by its table.
ALTER TABLE IF EXISTS office_floor RENAME TO company_floor;
ALTER INDEX IF EXISTS office_floor_pkey_uidx RENAME TO company_floor_pkey_uidx;
ALTER INDEX IF EXISTS office_floor_workspace_position_idx RENAME TO company_floor_workspace_position_idx;
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'company_floor'::regclass AND conname = 'office_floor_pkey') THEN
        ALTER TABLE company_floor RENAME CONSTRAINT office_floor_pkey TO company_floor_pkey;
    END IF;
    IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'company_floor'::regclass AND conname = 'office_floor_name_check') THEN
        ALTER TABLE company_floor RENAME CONSTRAINT office_floor_name_check TO company_floor_name_check;
    END IF;
END $$;
